// Sound effects and music for Neon Warden. Files are generated by Tools/neon-warden/make_audio.py.
const last = new Map();
const audio = () => window.Piston?.audio;

export const sfx = {
    /** Plays assets/sfx/<name>.wav; `minGap` (seconds) throttles rapid repeats of the same sound. */
    play(name, { volume = 1, pitch = 1, minGap = 0.035, jitter = 0 } = {}) {
        const a = audio();
        if (!a) return null;
        const now = performance.now() / 1000;
        if (now - (last.get(name) ?? -1) < minGap) return null;
        last.set(name, now);
        return a.play(`./assets/sfx/${name}.wav`, { volume, pitch: pitch * (1 + (Math.random() - 0.5) * jitter), bus: 'sfx' });
    },
};

export const music = {
    current: null, voice: null,
    play(name, volume = 0.5) {
        if (this.current === name) return;
        this.stop();
        this.voice = audio()?.play(`./assets/music/${name}.wav`, { loop: true, bus: 'music', volume }) ?? null;
        this.current = name;
    },
    stop() { try { this.voice?.stop(); } catch (e) { /* already stopped */ } this.voice = null; this.current = null; },
};
